//! Instance names, hierarchical paths and net labels.

use std::{collections::HashMap, fmt};

use uuid::Uuid;

use crate::trace::Trace;

/// Namespace of the UUID v5 values generated by this crate.
const UUID_NAMESPACE: Uuid = Uuid::from_u128(0x472d540a_1f37_4bd8_a634_de0cd5e638fb);

/// Character reserved for automatic instance names (`R#1`, `OpAmpStage#2`, ...).
pub(crate) const AUTO_NAME_SEPARATOR: char = '#';

/// Escapes characters that have a special meaning in KiCad net names and sheet paths.
pub fn escape_name(name: &str) -> String {
    name.replace('/', "{slash}")
}

/// Reverses [`escape_name`].
pub fn unescape_name(name: &str) -> String {
    name.replace("{slash}", "/")
}

/// Path of subcircuit instance names from the root, e.g. `["amp_left", "stage#1"]`.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, Default)]
pub struct HierPath(pub Vec<String>);

impl HierPath {
    pub(crate) fn prepended(&self, name: &str) -> Self {
        let mut names = Vec::with_capacity(self.0.len() + 1);
        names.push(name.to_string());
        names.extend_from_slice(&self.0);
        HierPath(names)
    }
}

impl HierPath {
    /// UUIDs of the subcircuit instances on the path, from the root.
    /// Each is derived from the instance names up to it, so it does not change between builds.
    pub fn uuids(&self) -> Vec<Uuid> {
        (1..=self.0.len())
            .map(|len| {
                let path = HierPath(self.0[..len].to_vec());
                Uuid::new_v5(&UUID_NAMESPACE, format!("subcircuit:{path}").as_bytes())
            })
            .collect()
    }

    /// The UUID path written as KiCad `tstamps` of a `sheetpath`: `/` at the root, otherwise `/uuid1/uuid2/`.
    pub fn tstamps(&self) -> String {
        let mut tstamps = String::from("/");
        for uuid in self.uuids() {
            tstamps.push_str(&uuid.to_string());
            tstamps.push('/');
        }
        tstamps
    }

    /// The UUID of a part with the instance name `name` in the subcircuit instance at this path.
    pub fn part_uuid(&self, name: &str) -> Uuid {
        Uuid::new_v5(
            &UUID_NAMESPACE,
            format!("part:{self}{}", escape_name(name)).as_bytes(),
        )
    }
}

impl fmt::Display for HierPath {
    /// `/` at the root, otherwise `/a/b/` (names are escaped).
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("/")?;
        for name in &self.0 {
            write!(f, "{}/", escape_name(name))?;
        }
        Ok(())
    }
}

pub use cuprite_wire_kicad_lib::naming::natural_cmp;

/// Checks an explicit instance name.
pub(crate) fn check_explicit_name(name: &str) -> Result<(), &'static str> {
    if name.is_empty() {
        Err("names must not be empty")
    } else if name.contains(AUTO_NAME_SEPARATOR) {
        Err("'#' is reserved for automatic names")
    } else {
        Ok(())
    }
}

/// The last path segment of a type name without generic arguments
/// (`my_crate::amp::OpAmpStage<f64>` -> `OpAmpStage`).
pub(crate) fn short_type_name<T: ?Sized>() -> String {
    let full = std::any::type_name::<T>();
    let without_generics = full.split('<').next().unwrap_or(full);
    without_generics
        .rsplit("::")
        .next()
        .unwrap_or(without_generics)
        .to_string()
}

/// Finds names equal to an earlier one when ASCII case is ignored. Returns, for each such name,
/// its index and the index of the first name it is equal to.
pub(crate) fn case_insensitive_duplicates<'a>(
    names: impl IntoIterator<Item = &'a str>,
) -> Vec<(usize, usize)> {
    let mut first_by_lowercase = HashMap::new();
    names
        .into_iter()
        .enumerate()
        .filter_map(|(i, name)| {
            let first = *first_by_lowercase
                .entry(name.to_ascii_lowercase())
                .or_insert(i);
            (first != i).then_some((i, first))
        })
        .collect()
}

/// A name given to a net.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum NetLabel {
    /// Connects every node with the same name anywhere in the circuit (like a KiCad power symbol
    /// or global label). The net is named `NAME`.
    Global(String),
    /// Connects nodes with the same name in the same (sub)circuit instance (like a KiCad local
    /// label). The net is named `/path/NAME`.
    Local(String),
}

impl NetLabel {
    pub fn global(name: impl Into<String>) -> Self {
        NetLabel::Global(name.into())
    }

    pub fn local(name: impl Into<String>) -> Self {
        NetLabel::Local(name.into())
    }

    pub fn name(&self) -> &str {
        match self {
            NetLabel::Global(name) | NetLabel::Local(name) => name,
        }
    }
}

/// A label attached to a node, with the subcircuit instance it was attached in.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NodeLabel {
    pub label: NetLabel,
    pub scope: HierPath,
    pub trace: Trace,
}

impl NodeLabel {
    /// The net name this label gives.
    pub fn net_name(&self) -> String {
        match &self.label {
            NetLabel::Global(name) => escape_name(name),
            NetLabel::Local(name) => format!("{}{}", self.scope, escape_name(name)),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_hier_path_display() {
        assert_eq!(HierPath::default().to_string(), "/");
        let path = HierPath(vec!["b/c".into()]).prepended("a");
        assert_eq!(path.to_string(), "/a/b{slash}c/");
    }

    #[test]
    fn test_uuids_depend_only_on_names() {
        let path = HierPath(vec!["a".into(), "b".into()]);
        assert_eq!(path.uuids(), path.clone().uuids());
        assert_eq!(path.uuids()[0], HierPath(vec!["a".into()]).uuids()[0]);
        assert_ne!(
            path.uuids()[1],
            HierPath(vec!["c".into(), "b".into()]).uuids()[1]
        );
        assert_eq!(HierPath::default().tstamps(), "/");
        let [a, b] = path.uuids()[..] else { panic!() };
        assert_eq!(path.tstamps(), format!("/{a}/{b}/"));
        assert_ne!(path.part_uuid("R#1"), path.part_uuid("R#2"));
        assert_ne!(path.part_uuid("x"), HierPath::default().part_uuid("x"));
    }

    #[test]
    fn test_short_type_name() {
        struct Generic<T>(T);
        assert_eq!(short_type_name::<Generic<Option<u8>>>(), "Generic");
        assert_eq!(short_type_name::<u8>(), "u8");
    }

    #[test]
    fn test_net_names() {
        let label = |label, scope: &[&str]| NodeLabel {
            label,
            scope: HierPath(scope.iter().map(|s| s.to_string()).collect()),
            trace: Trace::default(),
        };
        assert_eq!(label(NetLabel::global("+3V3"), &["a"]).net_name(), "+3V3");
        assert_eq!(label(NetLabel::local("OUT"), &[]).net_name(), "/OUT");
        assert_eq!(
            label(NetLabel::local("I/O"), &["amp"]).net_name(),
            "/amp/I{slash}O"
        );
        assert_eq!(unescape_name("/amp/I{slash}O"), "/amp/I/O");
    }

    #[test]
    fn test_check_explicit_name() {
        assert!(check_explicit_name("amp_left").is_ok());
        assert!(check_explicit_name("").is_err());
        assert!(check_explicit_name("R#1").is_err());
    }
}
